import re

src = open('source.kt').read()

out = []
i, n = 0, len(src)
state = 'code'  # code, line, block, string, triple, char
block_depth = 0
line_start = True  # tracks whether current output line has only whitespace so far
line_buf_start_idx = 0

# We'll build output line by line to drop comment-only lines.
lines_out = []
cur_line = []          # chars for current output line
cur_line_had_code = False
i, n = 0, len(src)
state = 'code'
block_depth = 0

def flush_line():
    global cur_line, cur_line_had_code
    if cur_line_had_code:
        lines_out.append(''.join(cur_line).rstrip() + '\n')
    # else: line was comment/whitespace only -> drop it
    cur_line = []
    cur_line_had_code = False

while i < n:
    c = src[i]
    nxt = src[i+1] if i+1 < n else ''
    if state == 'code':
        if c == '/' and nxt == '/':
            state = 'line'; i += 2; continue
        if c == '/' and nxt == '*':
            state = 'block'; block_depth = 1; i += 2; continue
        if c == '"':
            if src[i:i+3] == '"""':
                state = 'triple'; cur_line.append('"""'); cur_line_had_code = True; i += 3; continue
            state = 'string'; cur_line.append(c); cur_line_had_code = True; i += 1; continue
        if c == "'":
            state = 'char'; cur_line.append(c); cur_line_had_code = True; i += 1; continue
        cur_line.append(c)
        if c != ' ' and c != '\t':
            cur_line_had_code = True
        if c == '\n':
            flush_line()
        i += 1; continue
    elif state == 'line':
        if c == '\n':
            state = 'code'
            cur_line.append('\n'); flush_line()
        i += 1; continue
    elif state == 'block':
        if c == '/' and nxt == '*':
            block_depth += 1; i += 2; continue
        if c == '*' and nxt == '/':
            block_depth -= 1; i += 2
            if block_depth == 0:
                state = 'code'
            continue
        if c == '\n':
            cur_line.append('\n'); flush_line()
        i += 1; continue
    elif state == 'string':
        cur_line.append(c)
        if c == '\\':
            if i+1 < n:
                cur_line.append(src[i+1]); i += 2; continue
        elif c == '"':
            state = 'code'
        elif c == '\n':  # unterminated; safety
            state = 'code'
            flush_line()
        i += 1; continue
    elif state == 'triple':
