        i += 1; continue
    elif state == 'char':
        cur_line.append(c)
        if c == '\\':
            if i+1 < n:
                cur_line.append(src[i+1]); i += 2; continue
        elif c == "'":
            state = 'code'
        i += 1; continue

if cur_line:
