KING_DIRS = BISHOP_DIRS + ROOK_DIRS


def _parse_fen(fen):
    placement, turn = fen.split()[:2]
    board = []
    for rank in placement.split("/"):
        row = []
        for ch in rank:
            if ch.isdigit():
                row.extend([None] * int(ch))
            else:
                row.append(ch)
        board.append(row)
    return board, turn


def _in_bounds(r, c):
    return 0 <= r < 8 and 0 <= c < 8


def _offset_moves(board, r, c, is_white, deltas):
    moves = []
    for dr, dc in deltas:
        nr, nc = r + dr, c + dc
        if _in_bounds(nr, nc):
            target = board[nr][nc]
            if target is None or target.isupper() != is_white:
                moves.append((r, c, nr, nc))
    return moves


def _slide_moves(board, r, c, is_white, dirs):
    moves = []
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        while _in_bounds(nr, nc):
            target = board[nr][nc]
            if target is None:
                moves.append((r, c, nr, nc))
            else:
                if target.isupper() != is_white:
                    moves.append((r, c, nr, nc))
                break
            nr += dr
            nc += dc
    return moves


def _pawn_moves(board, r, c, is_white):
    moves = []
    d = -1 if is_white else 1
    start_rank = 6 if is_white else 1
    last_rank = 0 if is_white else 7
    nr = r + d
