    board = []
    for rank in placement.split("/"):
        row = []
        for ch in rank:
            if ch.isdigit():
                row.extend([None] * int(ch))
            else:
                row.append(ch)
        board.append(row)
    castling = set() if len(parts) < 4 or parts[3] == "-" else set(parts[3])
    return board, turn, castling


