def _is_attacked(board, r, c, by_white):
    pr = r + (1 if by_white else -1)
    pawn = "P" if by_white else "p"
    for dc in (-1, 1):
        nc = c + dc
        if _in_bounds(pr, nc) and board[pr][nc] == pawn:
            return True
    knight = "N" if by_white else "n"
    for dr, dc in KNIGHT_DELTAS:
        nr, nc = r + dr, c + dc
        if _in_bounds(nr, nc) and board[nr][nc] == knight:
            return True
    king = "K" if by_white else "k"
    for dr, dc in KING_DIRS:
        nr, nc = r + dr, c + dc
        if _in_bounds(nr, nc) and board[nr][nc] == king:
            return True
    slider_sets = (
        (BISHOP_DIRS, "BQ" if by_white else "bq"),
        (ROOK_DIRS, "RQ" if by_white else "rq"),
    )
    for dirs, pieces in slider_sets:
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while _in_bounds(nr, nc):
                piece = board[nr][nc]
                if piece is not None:
                    if piece in pieces:
                        return True
                    break
                nr += dr
                nc += dc
    return False


def _castling_moves(board, is_white, castling):
    moves = []
    row = 7 if is_white else 0
    king = "K" if is_white else "k"
    rights = ("K", "Q") if is_white else ("k", "q")
    if board[row][4] != king:
        return moves
    enemy = not is_white
    if rights[0] in castling and board[row][5] is None and board[row][6] is None:
        if (not _is_attacked(board, row, 4, enemy)
                and not _is_attacked(board, row, 5, enemy)
                and not _is_attacked(board, row, 6, enemy)):
            moves.append((row, 4, row, 6))
    if rights[1] in castling and board[row][1] is None and board[row][2] is None and board[row][3] is None:
        if (not _is_attacked(board, row, 4, enemy)
                and not _is_attacked(board, row, 3, enemy)
                and not _is_attacked(board, row, 2, enemy)):
            moves.append((row, 4, row, 2))
    return moves


def _generate(board, turn, castling):
    is_white = turn == "w"
