            elif kind == "q":
                moves.extend(_slide_moves(board, r, c, is_white, KING_DIRS))
            else:
                moves.extend(_offset_moves(board, r, c, is_white, KING_DIRS))
    moves.extend(_castling_moves(board, is_white, castling))
    return moves


def _apply(board, move, turn, castling):
    fr, fc, tr, tc = move
    new_board = [row[:] for row in board]
    piece = new_board[fr][fc]
    new_board[tr][tc] = piece
    new_board[fr][fc] = None
    rights = castling
    if piece == "K":
        if tc == 6:
            new_board[7][5] = new_board[7][7]
            new_board[7][7] = None
        elif tc == 2:
            new_board[7][3] = new_board[7][0]
            new_board[7][0] = None
        rights = rights - {"K", "Q"}
    elif piece == "k":
        if tc == 6:
            new_board[0][5] = new_board[0][7]
            new_board[0][7] = None
        elif tc == 2:
            new_board[0][3] = new_board[0][0]
            new_board[0][0] = None
        rights = rights - {"k", "q"}
    if piece in ("R", "r") and (fr, fc) in ROOK_RIGHTS:
        rights = rights - {ROOK_RIGHTS[(fr, fc)]}
    if (tr, tc) in ROOK_RIGHTS:
        rights = rights - {ROOK_RIGHTS[(tr, tc)]}
    return new_board, "b" if turn == "w" else "w", rights


