def _move_is_legal(board, turn, castling, ep, move):
    new_board, _, _, _ = _apply(board, move, turn, castling, ep)
    king = _find_king(new_board, turn == "w")
    if king is None:
        return False
    return not _is_attacked(new_board, king[0], king[1], turn != "w")


def _legal_generate(board, turn, castling, ep):
    return [m for m in _generate(board, turn, castling, ep)
            if _move_is_legal(board, turn, castling, ep, m)]


def legal_moves(fen: str) -> list[str]:
    board, turn, castling, ep = _parse_fen(fen)
    return [_to_uci(m) for m in _legal_generate(board, turn, castling, ep)]


def _perft(board, turn, castling, ep, depth):
    if depth == 0:
        return 1
    total = 0
    for move in _legal_generate(board, turn, castling, ep):
        child_board, child_turn, child_castling, child_ep = _apply(board, move, turn, castling, ep)
        total += _perft(child_board, child_turn, child_castling, child_ep, depth - 1)
    return total
